"use strict";
(function($){
    $.fn.SumoSelect = function(options){
        var triggerEvent = function(elem, type){
            var event = null;
            if(typeof Event === "function"){
                event = new Event(type,{bubbles:true});
            } else {
                event = document.createEvent("Event");
                event.initEvent(type,true,true);
            }
            elem.dispatchEvent(event);
        };

        if(window.NodeList && !NodeList.prototype.forEach){
            NodeList.prototype.forEach = Array.prototype.forEach;
        }

        var defaults = {
            placeholder:"Select Here",
            csvDispCount:3,
            captionFormat:"{0} Selected",
            captionFormatAllSelected:"{0} all selected!",
            floatWidth:400,
            forceCustomRendering:false,
            nativeOnDevice:["Android","BlackBerry","iPhone","iPad","iPod","Opera Mini","IEMobile","Silk"],
            outputAsCSV:false,
            csvSepChar:",",
            okCancelInMulti:false,
            isClickAwayOk:false,
            triggerChangeCombined:true,
            selectAll:false,
            selectAllPartialCheck:true,
            search:false,
            searchText:"Search...",
            searchFn:function(text, search){ return text.toLowerCase().indexOf(search.toLowerCase()) < 0; },
            noMatch:'No matches for "{0}"',
            prefix:"",
            locale:["OK","Cancel","Select All","Clear all"],
            up:false,
            showTitle:true,
            clearAll:false,
            closeAfterClearAll:false,
            max:null,
            renderLi:function(li,opt){ return li; }
        };

        var settings = $.extend({}, defaults, options);

        return this.each(function(){
            var select = this;

            if(!this.sumo && $(this).is("select")){
                var S = {
                    E:$(select),
                    is_multi: $(select).attr("multiple"),
                    select:"",
                    caption:"",
                    placeholder:"",
                    optDiv:"",
                    CaptionCont:"",
                    ul:"",
                    is_floating:false,
                    is_opened:false,
                    mob:false,
                    Pstate:[],
                    lastUnselected:null,
                    selectedCount:0,
                    optIdx:0, // unique id counter for options

                    /* --- 메서드 정의 --- */
                    prepItems:function(opts, disabled){
                        var self=this, lis=[];
                        $(opts).each(function(i,opt){
                            var $opt=$(opt);
                            if($opt.is("optgroup")){
                                var li=$('<li class="group '+(opt.disabled?"disabled":"")+'"><label></label><ul></ul></li>');
                                li.find("label").text($opt.attr("label"));
                                li.find("ul").append(self.prepItems($opt.children(), opt.disabled));
                                lis.push(li);
                            } else {
                                lis.push(self.createLi($opt, disabled));
                            }
                        });
                        return lis;
                    },

                    createLi:function(opt, disabled){
                        var self=this;
                        if(!opt.attr("value")) opt.attr("value", opt.val());

                        var ariaText = (opt.text() || "").toString().trim();
                        var id = "sumo-opt-" + (self.optIdx++);
                        var labelId = id + "-label";

                        var li = $('<li class="opt" role="option" aria-selected="false"></li>');
                        li.attr('id', id);

                        if(self.is_multi){
                            li.append('<span aria-hidden="true"><i></i></span>');
                        }

                        var $label = $('<label></label>').attr('id', labelId).text(opt.text());
						li.append($label);

                        li.data("opt", opt);
                        opt.data("li", li);

                        if(opt[0].disabled || disabled){
                            li.addClass("disabled");
                            li.attr("aria-disabled", "true");
                        } else {
                            li.attr("aria-disabled", "false");
                        }

                        if(opt[0].selected){
                            li.addClass("selected").attr("aria-selected","true");
                            self.selectedCount++;
                        }

                        if(opt.attr("class")) li.addClass(opt.attr("class"));
                        if(opt.attr("title")) li.attr("title", opt.attr("title"));

                        if(ariaText) {
                            li.attr("aria-label", ariaText);
                            
                        }

                        li.attr('tabindex','-1');

                        self.onOptClick(li);

                        return settings.renderLi(li,opt);
                    },

                    onOptClick:function(li){
                        var self=this;
                        li.click(function(e){
                            e.stopPropagation();
                            var $li=$(this);
                            if($li.hasClass("disabled")) return;

                            try { self.select.attr('aria-activedescendant', $li.attr('id')); } catch(err){}

                            if(self.is_multi){
                                $li.toggleClass("selected");
                                var isSel = $li.hasClass("selected");
                                $li.attr("aria-selected", isSel ? 'true':'false');
                                $li.data("opt")[0].selected = isSel;
                                if(! $li.data("opt")[0].selected ){
                                    self.lastUnselected = $li.data("opt")[0].textContent;
                                    self.selectedCount--;
                                } else {
                                    self.selectedCount++;
                                }
                                if(settings.max) self._handleMax();
                                self.selAllState();
                            } else {
                                self.ul.find("li.selected").removeClass("selected").attr("aria-selected","false");
                                $li.addClass("selected").attr("aria-selected","true");
                                $li.data("opt")[0].selected = true;
                                self.selectedCount = 1;
                            }

                            try { self.ul.find("li").not($li).attr('tabindex','-1'); $li.attr('tabindex','0')[0].focus(); } catch(err){}

                            if(!(self.is_multi && settings.triggerChangeCombined && (self.is_floating || settings.okCancelInMulti))){
                                self.setText();
                                self.callChange();
                            }
                            if(!self.is_multi) self.hideOpts();
                        });
                    },

                    multiSelelect:function(){
                        var self=this;
                        self.optDiv.addClass("multiple");
                        self.okbtn=$('<p tabindex="0" class="btnOk" role="button">'+settings.locale[0]+'</p>').click(function(){ self._okbtn(); self.hideOpts(); });
                        self.cancelBtn=$('<p tabindex="0" class="btnCancel" role="button">'+settings.locale[1]+'</p>').click(function(){ self._cnbtn(); self.hideOpts(); });
                        var btns=self.okbtn.add(self.cancelBtn);
                        self.optDiv.append($('<div class="MultiControls">').append(btns));
                        btns.on("keydown.sumo", function(e){
                            var btn=$(this);
                            switch(e.which){
                                case 32: case 13: btn.trigger("click"); break;
                                case 27: self._cnbtn(); self.hideOpts(); return;
                                default:;
                            }
                            e.stopPropagation(); e.preventDefault();
                        });
                    },

                    Search:function(){
                        var self=this;
                        var caption=self.CaptionCont.addClass("search");
                        var noMatch=$('<p class="no-match">');
                        var searchFn=options.searchFn && typeof options.searchFn==="function"? options.searchFn: settings.searchFn;

                        self.ftxt=$('<input type="text" class="search-txt" value="" autocomplete="off" aria-label="옵션 검색">')
                            .on("click", function(e){ e.stopPropagation(); })
                            .attr("placeholder", settings.searchText);
                        caption.append(self.ftxt);
                        self.optDiv.children("ul").after(noMatch);

                        self.ftxt.on("keyup.sumo", function(){
                            var val=self.ftxt.val();
                            var visible=false;
                            self.optDiv.find("ul.options li.opt").each(function(){
                                var li=$(this), hidden=searchFn(li.text(), val);
                                li.toggleClass("hidden", hidden);
                                if(!hidden) visible=true;
                            });
                            self.optDiv.find("li.group").each(function(){
                                var grp=$(this);
                                if(grp.find("li:not(.hidden)").length>0) grp.removeClass("hidden"); else grp.addClass("hidden");
                            });
                            noMatch.html(settings.noMatch.replace(/\{0\}/g,"<em></em>")).toggle(!visible);
                            noMatch.find("em").text(val);
                            self.selAllState();
                        });
                    },

                    ClearAll:function(){
                        var self=this;
                        if(self.is_multi){
                            self.selAll=$('<p class="reset-all"><span><i></i></span><label>'+settings.locale[3]+'</label></p>');
                            self.optDiv.addClass("resetAll");
                            self.selAll.on("click", function(){ self.toggSelAll(false,1); if(settings.closeAfterClearAll) self.hideOpts(); });
                            self.optDiv.prepend(self.selAll);
                        }
                    },

                    SelAll:function(){
                        var self=this;
                        if(self.is_multi){
                            self.selAll=$('<p class="select-all"><span><i></i></span><label>'+settings.locale[2]+'</label></p>');
                            self.optDiv.addClass("selall");
                            self.selAll.on("click", function(){ self.toggSelAll(!self.selAll.hasClass("selected"),1); self.selAllState(); });
                            self.optDiv.prepend(self.selAll);
                        }
                    },

                    selAllState:function(){
                        if(settings.selectAll && this.is_multi){
                            var c=0,d=0;
                            this.optDiv.find("li.opt:not(.disabled):not(.hidden)").each(function(i,f){
                                if($(f).hasClass("selected")) c++; d++;
                            });
                            if(c===d) this.selAll.removeClass("partial").addClass("selected");
                            else if(c===0) this.selAll.removeClass("selected partial");
                            else if(settings.selectAllPartialCheck) this.selAll.addClass("partial").removeClass("selected");
                        }
                    },

                    _handleMax:function(){
                        var self=this;
                        if(settings.max){
                            if(self.selectedCount >= +settings.max){
                                self.optDiv.find("li.opt").not(".hidden").not(".selected").addClass("temporary-disabled disabled").attr("aria-disabled","true");
                            } else {
                                self.optDiv.find("li.opt.temporary-disabled").removeClass("temporary-disabled disabled").attr("aria-disabled","false");
                            }
                        }
                    },

                    floatingList:function(){
                        var self=this;
                        self.is_floating=$(window).width()<=settings.floatWidth;
                        self.optDiv.toggleClass("isFloating",self.is_floating);
                        if(!self.is_floating) self.optDiv.css("height","");
                        self.optDiv.toggleClass("okCancelInMulti",settings.okCancelInMulti && !self.is_floating);
                    },

                    isMobile:function(){
                        for(var i=0;i<settings.nativeOnDevice.length;i++)
                            if(navigator.userAgent.toLowerCase().indexOf(settings.nativeOnDevice[i].toLowerCase())>=0) return settings.nativeOnDevice[i];
                        return false;
                    },

                    setNativeMobile:function(){
                        var self=this;
                        self.E.addClass("SelectClass");
                        self.mob=true;
                        self.E.change(function(){ self.setText(); });
                    },

                    setText:function(){
                        var self=this;
                        var b=self.E.find(":checked").not(":disabled");
                        var txt="";
                        if(self.is_multi){
                            if(b.length>settings.csvDispCount){
                                if(b.length===self.E.find("option").length && settings.captionFormatAllSelected)
                                    txt=settings.captionFormatAllSelected.replace(/\{0\}/g,b.length);
                                else txt=settings.captionFormat.replace(/\{0\}/g,b.length);
                            } else txt=b.toArray().map(function(o){ return o.innerText; }).join(", ");
                        } else txt=b.text();
                        self.placeholder=txt?settings.prefix+" "+txt:settings.placeholder;
                        self.caption.text(self.placeholder);
                        if(settings.showTitle) self.CaptionCont.attr("title", self.placeholder);
                        if(settings.outputAsCSV && self.is_multi){
                            var input=self.select.find("input.HEMANT123");
                            if(input.length) input.val(self.getSelStr());
                        }
                    },

                    getSelStr:function(){
                        var arr=[]; this.E.find("option:checked").each(function(){ arr.push($(this).val()); });
                        return arr.join(settings.csvSepChar);
                    },

                    showOpts:function(){
                        var self=this;
                        if(!self.E.attr("disabled")){
                            self.is_opened=true;
                            self.select.addClass("open").attr("aria-expanded","true");
                            self.optDiv.show();
                            if(self.ftxt) self.ftxt.focus();
                            $(document).on("click.sumo", function(e){
                                if(!self.select.is(e.target) && self.select.has(e.target).length===0){
                                    if(!self.is_opened) return;
                                    self.hideOpts();
                                    if(settings.okCancelInMulti){
                                        settings.isClickAwayOk?self._okbtn():self._cnbtn();
                                    }
                                }
                            });
                            if(self.is_floating){
                                var h=self.optDiv.children("ul").outerHeight()+2;
                                if(self.is_multi) h+=+self.optDiv.css("padding-bottom");
                                self.optDiv.css("height",h);
                                $("body").addClass("sumoStopScroll");
                            }
                            self.setPstate();
                        }
                    },

                    hideOpts:function(){
                        var self=this;
                        if(self.is_opened){
                            self.is_opened=false;
                            self.select.removeClass("open").attr("aria-expanded","false");
                            self.optDiv.hide();
                            $(document).off("click.sumo");
                            $("body").removeClass("sumoStopScroll");
                            if(settings.search && self.ftxt){ self.ftxt.val(""); self.ftxt.trigger("keyup.sumo"); }
                        }
                    },

                    _okbtn:function(){ var self=this; self.callChange(); self.setText(); },
                    _cnbtn:function(){ var self=this;
                        self.E.find("option:checked").each(function(){ this.selected=false; });
                        self.optDiv.find("li.selected").removeClass("selected").attr("aria-selected","false");
                        for(var i=0;i<self.Pstate.length;i++)
                            self.E.find("option")[self.Pstate[i]].selected=true;
                        self.optDiv.find("li.opt").each(function(idx,li){
                            if(self.E.find("option")[idx].selected) $(li).addClass("selected").attr("aria-selected","true");
                        });
                    },

                    callChange:function(){
                        this.E.get().forEach(function(el){ triggerEvent(el,"change"); triggerEvent(el,"click"); });
                    },

                    toggSelAll:function(val){
                        var self=this;
                        if(self.is_multi){
                            if(val) self.E.find("option:not(:checked):not(:disabled):not(.hidden)").each(function(){ this.selected=true; $(this).data("li").addClass("selected").attr("aria-selected","true"); });
                            else self.E.find("option:checked:not(:disabled):not(.hidden)").each(function(){ this.selected=false; $(this).data("li").removeClass("selected").attr("aria-selected","false"); });
                        } else {
                            self.E[0].selectedIndex=-1;
                        }
                        self.setText();
                        self.setPstate();
                        if(self.selAll) self.selAll.toggleClass("selected", !!val).removeClass("partial");
                    },

                    basicEvents:function(){
                        var self=this;
                        self.CaptionCont.on("click", function(e){ self.is_opened?self.hideOpts():self.showOpts(); e.stopPropagation(); });

                        self.select.on("keydown.sumo", function(e){
                            switch(e.which){
                                case 38: self.nav(true); break;
                                case 40: self.nav(false); break;
                                case 13: self.is_opened?self.ul.find("li.opt.sel").trigger("click"):self.setOnOpen(); break;
                                case 32: if(settings.search && self.ftxt.is(e.target)) return; break;
                                case 27: if(settings.okCancelInMulti) self._cnbtn(); self.hideOpts(); break;
                                default: return;
                            }
                            e.preventDefault();
                        });
                        $(window).on("resize.sumo", function(){ self.floatingList(); });
                    },

                    nav:function(up){
                        var self=this;
                        var sel=self.ul.find("li.opt.sel:not(.hidden)");
                        var all=self.ul.find("li.opt:not(.disabled):not(.hidden)");
                        var idx=all.index(sel);
                        var next=null;
                        if(sel.length){
                            if(up && idx>0) next=all.eq(idx-1);
                            else if(!up && idx<all.length-1) next=all.eq(idx+1);
                            else return;
                            sel.removeClass("sel").attr('tabindex','-1');
                            next.addClass("sel").attr('tabindex','0');
                            try { next[0].focus(); } catch(err){}
                            try { self.select.attr('aria-activedescendant', next.attr('id')); } catch(err){}
                            var h=self.ul.scrollTop(), top=next.position().top+h;
                            if(top >= h+self.ul.height()-next.outerHeight()) self.ul.scrollTop(top-self.ul.height()+next.outerHeight());
                            if(top<h) self.ul.scrollTop(top);
                        } else self.setOnOpen();
                    },

                    setOnOpen:function(){ 
                        var self=this; 
                        var li=self.optDiv.find("li.opt:not(.hidden)").eq(settings.search?0:self.E[0].selectedIndex); 
                        li.addClass("sel").attr('tabindex','0'); 
                        try { li[0].focus(); } catch(err){}
                        try { self.select.attr('aria-activedescendant', li.attr('id')); } catch(err){}
                        self.showOpts(); 
                    },

                    createElems:function(){
                        var self=this;
                        var checked=self.E.find("option:checked");
                        checked.each(function(){ this.selected=true; });

                        self.E.wrap('<div class="SumoSelect" tabindex="0" role="combobox" aria-expanded="false">');
                        self.select=self.E.parent();
                        self.select.attr("aria-haspopup","listbox");

                        var selLabel = self.E.attr("aria-label") || self.E.attr("title") || self.E.attr("name");
                        if(selLabel) self.select.attr("aria-label", selLabel);

                        self.caption=$("<span>");
                        self.CaptionCont=$('<p class="CaptionCont SelectBox '+self.E.attr("class")+'"><label><i></i></label></p>')
                            .attr("style",self.E.attr("style")).prepend(self.caption);
                        self.select.append(self.CaptionCont);

                        if(!self.is_multi) settings.okCancelInMulti=false;
                        if(self.E.attr("disabled")) self.select.addClass("disabled").removeAttr("tabindex");
                        if(settings.outputAsCSV && self.is_multi && self.E.attr("name")){
                            self.select.append($('<input class="HEMANT123" type="hidden"/>').attr("name", self.E.attr("name")).val(self.getSelStr()));
                            self.E.removeAttr("name");
                        }
                        if(self.isMobile() && !settings.forceCustomRendering) self.setNativeMobile();
                        else{
                            self.E.addClass("SumoUnder").attr({
							    "tabindex": "-1",
							    "aria-hidden": "true"
							});
                            self.optDiv=$('<div class="optWrapper '+(settings.up?"up":"")+'">');
                            
                            self.optDiv.on('focusout', function(e) {
							    // optWrapper 안의 요소에서 바깥으로 포커스가 완전히 이동했을 때만 닫기
							    if (!self.optDiv[0].contains(e.relatedTarget)) {
							        self.hideOpts();
							    }
							});
                            
                            self.floatingList();
                            self.ul=$('<ul class="options" role="listbox">');
                            if(self.is_multi) self.ul.attr('aria-multiselectable','true');
                            self.optDiv.append(self.ul);
                            if(settings.clearAll && self.is_multi) self.ClearAll();
                            if(settings.selectAll && self.is_multi && !settings.max) self.SelAll();
                            if(settings.search) self.Search();
                            self.ul.append(self.prepItems(self.E.children()));
                            if(self.is_multi) self.multiSelelect();
                            self.select.append(self.optDiv);
                            self._handleMax();
                        }
                        self.basicEvents();
                    },

                    setPstate:function(){ 
                        var self=this; 
                        self.Pstate=[]; 
                        self.E.find("option").each(function(idx,opt){ if(opt.selected) self.Pstate.push(idx); }); 
                    },

                    init:function(){ this.createElems(); this.setText(); },

                    unload:function(){
                        var self=this;
                        self.select.find(".optWrapper, .CaptionCont").remove();
                        self.E.removeClass("SumoUnder SelectClass").unwrap();
                        self.E.removeData("li");
                        delete self.E[0].sumo;
                        return self.E;
                    },

                    reload:function(){
                        var self=this;
                        if(!self) return $(this).SumoSelect(settings);
                        var sel = self.unload();
                        return $(sel).SumoSelect(settings);
                    }
                };

                select.sumo=S;
                S.init();
            }
        });
    };
})(jQuery);
